/* Acerca de ZunzunOS */
#include "z.h"
#include "version.h"
static void bird(zwin *w, int x, int y, int s) { for (int i = 0; i < s; i++) { int h = i * 3 / 5; g_rect(w, x + i, y - h / 2 + s / 6, 1, h + 1, 0x14B8A6); } g_circle(w, x + s + s / 8, y + s / 8, s / 4, 0x5EEAD4, 1); g_line(w, x + s + s / 3, y + s / 8, x + s * 2, y, 0x5EEAD4); for (int i = 0; i < s / 2; i++) g_line(w, x + s / 2 + i, y - i / 8, x + s / 4 + i / 2, y - s / 2 - i / 3, 0x5EEAD4); }
static zwin *W; static void draw(void) { zs_area(W, 0, 0, W->w, W->h, 0); g_grad(W, 0, 0, W->w, 150, 0x0B3B3C, 0x134E4A); bird(W, 28, 80, 62); g_text2(W, 170, 28, "ZunzúnOS", 0xFFFFFF, 4); { char v[80]; snprintf(v, 80, "%s %s  ·  %s", tr("Versión"), ZZ_VERSION, ZZ_VERSION_FECHA); g_text(W, 172, 100, v, 0x99F6E4); } g_rect(W, 0, 150, W->w, W->h - 150, 0xFFFFFF); g_textb(W, 28, 170, "Un OS 100% independiente, libre y realmente privado.", 0x0F766E); static const char *L[] = {"Escrito desde cero: kernel, controladores y programas propios.", "Sin cuentas, sin nube y sin telemetría.", "Tus datos se quedan en tus discos.", "Pensado para rescatar archivos, escribir sin distracciones", "y trabajar con un equipo que obedece solo a su dueño."}; int y = 200; for (int i = 0; i < 5; i++) { g_text(W, 28, y, L[i], 0x1F2937); y += 20; } g_rect(W, 28, y + 8, W->w - 56, 1, 0xC4C9D2); g_text(W, 28, y + 22, "Creado por", 0x6B7280); g_text2(W, 28, y + 40, "Tony Fluxa", 0x0F766E, 2); g_text(W, 28, y + 76, "tonyfluxa.top", 0x1F2937); zsys s; z_sysinfo(&s); char b[100]; snprintf(b, 100, _("%lu MB de memoria  -  arranque %s"), s.mem_total >> 20, s.boot_mode == 2 ? "UEFI" : "BIOS"); g_text(W, 300, y + 50, b, 0x6B7280); g_text(W, 300, y + 70, "Licencia 0BSD: úsalo, cópialo y modifícalo libremente.", 0x6B7280); g_text(W, 300, y + 90, "Tipografia VGA de SeaBIOS (LGPL)", 0x6B7280); zs_show(W); zw_present(W); }
int main(const char *a) { W = zw_new("Acerca de ZunzunOS", -1, 0, 760, 450, WF_DECOR); draw(); z_log("[prueba] acerca abierto"); zevent e; for (;;) if (z_event(&e, -1)) { if (zs_event(W, &e)) draw(); else if (e.type == EV_REDRAW) draw(); else if (e.type == EV_CLOSE || (e.type == EV_KEY && e.ch == 27)) return 0; } }
